import{_ as i,l,o as e,c as s,v as o,p as n,x as r,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"霍姆斯特罗姆充足统计","description":"","frontmatter":{"title":"霍姆斯特罗姆充足统计","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/holmstrom-informativeness.md","filePath":"econ/holmstrom-informativeness.md","lastUpdated":1789023840000}'),h={name:"econ/holmstrom-informativeness.md"};function E(c,a,_,f,x,B){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="霍姆斯特罗姆充足统计" tabindex="-1">霍姆斯特罗姆充足统计 <a class="header-anchor" href="#霍姆斯特罗姆充足统计" aria-label="Permalink to &quot;霍姆斯特罗姆充足统计&quot;">​</a></h1><div class="epigraph"><p>对行动而言，合同只应依赖其充足统计量；再写入无关噪声，只增加无谓风险，不能改进激励。</p><footer>—— Holmström, Moral Hazard and Observability, Bell Journal of Economics, 1979</footer></div><p><a href="/econ/moral-hazard">上一课</a>说明合同只能写在可验证结果上，激励等于把风险塞给代理人。缺口是：可验证变量往往有一串——产出、同行产出、天气、股价。哪些该进 \\(w(\\cdot)\\)？本课钉充足统计 / 信息量原则，不把 IC–IR 规划写全，也不把有限责任写成下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>行动 \\(a\\) 不可写入合同。观察到的是 \\(x\\)，或许还有 \\(y\\)。似然 \\(f(x,y\\mid a)\\)。若 \\(x\\) 已是 \\(a\\) 的充足统计，即 \\(f(x,y\\mid a)=g(y\\mid x)\\,h(x\\mid a)\\)，则 \\(y\\) 在给定 \\(x\\) 后不含关于 \\(a\\) 的信息。最优合同可以写成 \\(w(x)\\)，不必再随 \\(y\\) 变。写入 \\(y\\) 只会在同一激励下加噪声，厌恶风险的代理人要求补偿，委托人更亏。</p><p>反过来：若 \\(y\\) 在给定 \\(x\\) 后仍改变 \\(a\\) 的似然比，则 \\(y\\) 有信息量，最优 \\(w\\) 应依赖 \\((x,y)\\)。这就是信息量原则（informativeness principle）。相对绩效是其推论：若 \\(y\\) 是别人的产出，共同冲击使 \\((x,y)\\) 比单看 \\(x\\) 更能滤掉运气，合同应写成对 \\(x-y\\) 或名次的奖惩。</p><h3 id="充足的是对行动-不是对产出" tabindex="-1">充足的是对行动，不是对产出 <a class="header-anchor" href="#充足的是对行动-不是对产出" aria-label="Permalink to &quot;充足的是对行动，不是对产出&quot;">​</a></h3><p>会计上的「利润」不必是对 \\(a\\) 的充足统计；股价若含有利润没有的关于努力的似然比，就应进合同。反过来，利润里若掺进代理人不可控的会计噪声，应尽量滤掉。原则问的是似然比 \\(f_a/f\\)，不是变量的名字。</p><p><span class="marginnote">Holmström 1979 的工资公式里，似然比 \\(f_a/f\\) 进入点态条件。若两个结果有相同似然比，应付相同工资——这正是「合同是似然比的函数」。单调似然比让工资对 \\(x\\) 单调，但是附加假设，不是充足统计本身。</span></p><p>风险中性且无财富约束时，把剩余卖给代理人，充足统计变得无足轻重：他承受全部风险，滤不滤噪声只影响他的方差，委托人已抽干。 厌恶风险时过滤才值钱。 信号若不可验证，原则帮不上：法庭执行不了 \\(y\\)。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：单代理人、隐藏行动、可验证信号向量。先对 \\((x,y)\\) 写似然比分解；再看最优规划的点态条件是否随 \\(y\\) 变。相对绩效：设 \\(x_i=a_i+\\eta+\\varepsilon_i\\)，则 \\(\\bar x\\) 含 \\(\\eta\\)，合同应依赖 \\(x_i-\\bar x\\)。团队生产里共同产出不可分，那是 1982 年另文，本课只借「共同冲击可滤」。</p>',12)),(e(),n(p,null,{default:r(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MH%5B%22%E9%9A%90%E8%97%8F%E8%A1%8C%E5%8A%A8%EF%BC%8C%E5%90%88%E5%90%8C%E5%86%99%E5%9C%A8%E7%BB%93%E6%9E%9C%E4%B8%8A%22%5D%20--%3E%20SIG%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%E4%BF%A1%E5%8F%B7%20x%2C%20y%22%5D%0A%20%20SIG%20--%3E%20SS%5B%22x%20%E5%85%85%E8%B6%B3%EF%BC%9F%22%5D%0A%20%20SS%20--%3E%20DROP%5B%22y%20%E4%B8%8D%E8%BF%9B%E5%B7%A5%E8%B5%84%22%5D%0A%20%20INF%5B%22y%20%E4%BB%8D%E6%94%B9%E4%BC%BC%E7%84%B6%E6%AF%94%22%5D%20--%3E%20USE%5B%22w%20%E4%BE%9D%E8%B5%96%20x%20%E4%B8%8E%20y%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>激励来自似然比，风险来自 \\(w\\) 的方差。最优是：在实施既定 \\(a\\) 的前提下最小化风险成本。充足统计把实施所需的似然比已经给齐，多出来的随机性没有实施价值，纯属成本。故最优把 \\(w\\) 写成似然比的函数，等价于写成充足统计的函数。相对绩效不是「公平」或「锦标赛文化」，是把 \\(\\eta\\) 从似然比里消掉。</p><p>与柠檬、信号不同：这里没有隐藏类型的切断或教育年限；信号是关于行动的，写进合同而不是写进工资等于产出的竞争报价。后课委托–代理会把 \\(\\mu(f_a/f)\\) 写进 FOC；本课只先限制自变量：不在无关维度上花钱买风险。相对绩效的限度是：共同冲击才该滤；若别人的产出主要含个体噪声，写成名次会把别人的行动噪声塞给自己，违反充足统计。团队里共同产出不可分到个人，那是 Holmström 1982，本课不把团队道德风险展开。</p><p>相对绩效不是公平口号：它只在 \\(y\\) 含共同冲击时改进似然比。 合谋会把这条过滤的好处吃掉，那是边界，不是原则失效。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>信号若同时是投资决策的输入（会计稳健、短视），信息量原则仍说「有信息就该用」，但多任务会反对强激励——那是 Holmström–Milgrom 1991，不是本课。合谋：相对绩效让代理人互相陷害或串通，滤噪声的好处被策略抵消。有限责任下，过滤的公式还在，但工资下界会强迫把惩罚换成租金，下一课。</p><p>后课默认：合同的自变量应是行动的充足统计；再加无关噪声严格变差。委托–代理规划在这个自变量上做。</p><h3 id="似然比相同则工资相同" tabindex="-1">似然比相同则工资相同 <a class="header-anchor" href="#似然比相同则工资相同" aria-label="Permalink to &quot;似然比相同则工资相同&quot;">​</a></h3><p>两个结果 \\(x,x&#39;\\) 若 \\(f_a/f\\) 相同，实施同一行动不需要区别它们。强行区别等于在无信息维度上打赌。这比「高产出高工资」更精确：运气堆出来的高产出，似然比未必高。</p><p><span class="marginnote">可观察不等于可验证，上节已钉。本课补一句：可验证也不等于有信息。法庭能执行的天气指数，若与 \\(a\\) 独立，仍不该进 \\(w\\)。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合同只应依赖对行动的充足统计；无关信号只加风险。</li><li>若额外信号改似然比，就必须用——信息量原则。</li><li>相对绩效是滤共同冲击，不是公平观念。</li><li>下一课：有限责任让「罚不到」破坏这套风险分担。</li><li>出处：Holmström, <em>Bell</em> 1979。</li></ul>',12))])}const y=i(h,[["render",E]]);export{A as __pageData,y as default};
